import{z as A,x as m,o as i,c as o,q as B,j as l,D as t,d as e,s,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"敏感度limits与聚合","description":"","frontmatter":{"title":"敏感度limits与聚合","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/omm-greeks-limits.md","filePath":"quant/omm-greeks-limits.md","lastUpdated":1791063341000}'),p={name:"quant/omm-greeks-limits.md"};function d(D,a,h,u,f,C){const r=m("Mermaid");return i(),o("div",null,[a[2]||(a[2]=B('<h1 id="敏感度limits与聚合" tabindex="-1">敏感度limits与聚合 <a class="header-anchor" href="#敏感度limits与聚合" aria-label="Permalink to &quot;敏感度limits与聚合&quot;">​</a></h1><div class="epigraph"><p>限额不是希腊字母的天花板，是情景损失的天花板；Gamma 本身不可比，可比的是同一次跳空里它值多少钱。</p><footer>—— 据 Hull, Options, Futures, and Other Derivatives 希腊字母与风险管理各章；限额架构据做市实务整理</footer></div><p><a href="/quant/omm-vol-position-ledger">上一课</a>把波动仓位折进期限桶，账本从此能读出「持有哪一段波动」。下一问是「允许多大」：每台、每账本、每个交易员允许多大的 Delta、Gamma、Vega 与隔夜损失，跨账本怎么加总，破了限走什么流程。本课写敏感度限额的定义、聚合与治理——它是 <a href="/quant/omm-book-layering">账本</a> 与报价曲线之间的闸门。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>裸希腊数字不可比。两千万的 Gamma 在平值短到期上是几次小跳空的量，在深虚值长到期上可能一整年都用不上；Vega 一千万分布在当周还是两年期，含义完全不同。若限额直接钉在希腊数字上，要么形同虚设，要么迫使交易员把仓位藏进限额没有覆盖的维度。缺的是把敏感度翻译成<strong>共同货币</strong>的规则：情景损失。</p><p><span class="marginnote">直觉类比：裸希腊数字像有人用「公斤、米、升」各报各的数，没法比大小；情景损失把它们统统换算成「同一次跳空里值多少钱」这一种货币，限额表才有统一的刻度，藏仓位也无处可藏。</span></p><p>第二个问题是聚合。四个交易员各自限内，加起来可以远超台子的承受力：相加把相关性当一，开根把相关性当零，两种错法都会在压力日兑现。</p><h3 id="先定情景-再定限额" tabindex="-1">先定情景，再定限额 <a class="header-anchor" href="#先定情景-再定限额" aria-label="Permalink to &quot;先定情景，再定限额&quot;">​</a></h3><p>把限额定义在同一组情景上：例如现货 \\(\\pm 2\\%\\)、\\(\\pm 4\\%\\) 乘隐波 \\(\\pm 3\\) 个点的网格，加上隔夜跳空与到期周专用情景。Gamma 限额写成 \\(\\tfrac12\\Gamma(\\Delta S)^2\\) 的损失上限，Vega 限额写成各期限桶同动 1 个点的上限，Vanna 与 <a href="/quant/higher-greeks">Charm</a> 折进「跌且波动升」与「现货不动过一夜」的情景。这样不同到期、不同执行价的仓位在限额表里说的是同一种话。</p><p><span class="marginnote">聚合规则要先聚仓位再算损失：把全部账本放在同一个情景里重估，得到总损失；而不是先算各账本的损失再挑一种相关性公式相加。前者对任何相关结构都对，后者只在相关性假设成立时对——压力日恰恰是假设失效日。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>限额体系四层：公司、台、账本、交易员，上层是下层的聚合加缓冲。每条限额写五要素：度量（哪个情景）、期限（日内、收盘、隔夜）、币种、软硬、审批人。软限破限要当日书面说明与减压计划，硬限破限系统直接拒新单。日内检查按节奏排：开盘前用隔夜情景重估一次，事件窗口另加频率。</p><p>聚合分两种口径。同标的净额聚合：同一合约的 Delta 直接抵消，这没有争议。跨标的聚合：用相关性矩阵，但要给「相关性趋一」的压力变体保留一条最严限额——危机里分散化最先失效。到期与 <a href="/quant/pin-risk">Pin</a> 专项限额独立于日常限额，因为它们的损失发生在容量最小、流动性最差的时刻。</p><p><span class="marginnote">数字实例：Gamma = 5000、现货 100，在 ±2% 跳空档，\\(\\tfrac12\\times5000\\times2^2=10000\\)，这一档情景里 Gamma 值 1 万元损失；同一仓位放进 ±4% 档就是 4 万元。损失按跳空幅度平方放大——这正是裸 Gamma 数字看不出危险、必须换算成情景损失的原因。</span></p>',14)),(i(),l(n,null,{default:t(()=>[s(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E4%BA%A4%E6%98%93%E5%91%98%E9%99%90%E9%A2%9D%22%5D%20--%3E%20T2%5B%22%E8%B4%A6%E6%9C%AC%E9%99%90%E9%A2%9D%22%5D%0A%20%20T2%20--%3E%20T3%5B%22%E5%8F%B0%E9%99%90%E9%A2%9D%22%5D%0A%20%20T3%20--%3E%20T4%5B%22%E5%85%AC%E5%8F%B8%E9%99%90%E9%A2%9D%22%5D%0A%20%20B%5B%22%E7%BB%9F%E4%B8%80%E6%83%85%E6%99%AF%E9%9B%86%22%5D%20--%3E%20T1%0A%20%20B%20--%3E%20T2%0A%20%20B%20--%3E%20T3%0A%20%20T2%20--%3E%7C%E7%A0%B4%E8%BD%AF%E9%99%90%7C%20E1%5B%22%E4%B9%A6%E9%9D%A2%E8%AF%B4%E6%98%8E%20%E5%87%8F%E5%8E%8B%E8%AE%A1%E5%88%92%22%5D%0A%20%20T2%20--%3E%7C%E7%A0%B4%E7%A1%AC%E9%99%90%7C%20E2%5B%22%E7%B3%BB%E7%BB%9F%E6%8B%92%E6%96%B0%E5%8D%95%20%E5%BC%BA%E5%88%B6%E5%87%8F%E4%BB%93%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("情景化为什么改变行为：交易员优化的是被度量的东西。裸 Gamma 限额催生「把 Gamma 藏进深虚值」的会计游戏——数字变小，\\(\\tfrac12\\Gamma(\\Delta S)^2\\) 在大跳空下不变甚至更大；情景限额使这类替换无处遁形，因为任何形状的仓位都要在同一个网格里报价。这也是 "),E("a",{href:"/quant/greeks-hedge"},"希腊对冲"),e(" 与限额的分工：对冲决定每天交易多少，限额决定被允许持有多少残余。")],-1)),a[5]||(a[5]=E("p",null,"聚合的机制难点在净额的时效：收盘净额可能掩盖日内两端各自触限的路径——上午多头触限、下午空头触限，收盘看什么都没发生。关键账本要加日内峰值限额，记当天的最大绝对暴露而不是收盘快照。",-1)),(i(),l(n,null,{default:t(()=>[s(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%8A%E5%8D%88%20%E5%BB%BA%E5%A4%9A%E5%A4%B4%22%5D%20--%3E%20B%5B%22%E5%A4%9A%E5%A4%B4%E6%9A%B4%E9%9C%B2%E8%A7%A6%E9%99%90%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%8D%88%E5%89%8D%20%E5%B9%B3%E6%8E%89%20%E5%87%80%E9%A2%9D%E4%B8%AD%E6%80%A7%22%5D%0A%20%20C%20--%3E%20D%5B%22%E4%B8%8B%E5%8D%88%20%E5%8F%8D%E5%90%91%E5%BB%BA%E7%A9%BA%E5%A4%B4%22%5D%0A%20%20D%20--%3E%20E%5B%22%E7%A9%BA%E5%A4%B4%E6%9A%B4%E9%9C%B2%E8%A7%A6%E9%99%90%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%94%B6%E7%9B%98%20%E5%87%80%E9%A2%9D%E6%8E%A5%E8%BF%91%E9%9B%B6%22%5D%0A%20%20F%20--%3E%20G%7B%22%E7%94%A8%E5%93%AA%E6%8A%8A%E5%B0%BA%E5%AD%90%3F%22%7D%0A%20%20G%20--%3E%7C%22%E6%94%B6%E7%9B%98%E5%BF%AB%E7%85%A7%22%7C%20H%5B%22%E7%9C%8B%E4%BC%BC%E4%BB%80%E4%B9%88%E9%83%BD%E6%B2%A1%E5%8F%91%E7%94%9F%22%5D%0A%20%20G%20--%3E%7C%22%E6%97%A5%E5%86%85%E5%B3%B0%E5%80%BC%22%7C%20I%5B%22%E5%BD%93%E6%97%A5%E6%9C%80%E5%A4%A7%E7%BB%9D%E5%AF%B9%E6%9A%B4%E9%9C%B2%E5%B7%B2%E8%A7%A6%E9%99%90%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p>不这么做会错在哪：只盯收盘净数的台，会在一次午后的单边行情里发现「限额从未被触发、损失却已经发生」；反过来，只盯峰值的台会被正常的往返行情天天误报。两把尺子都要有，且写明谁对哪把负责。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>情景集是有限维的，真正的尾部（相关结构突变、停牌、<a href="/quant/overnight-gap-hedge">隔夜跳空</a> 叠加到期）落在网格之外，限额之外还要有 <a href="/quant/gamma-flip-level">压力测试</a> 与硬性减仓触发。限额不是预测：破限不等于犯错，长期不破限往往说明情景集太松或业务在收缩。度量口径变更（换情景、换桶）等价于改限额，必须走与限额变更相同的审批，否则每一次「技术性调整」都是一次静默的放松。</p><p><span class="marginnote">常见误区：初学者容易把限额当成绩单——「破限 = 犯错，长期不破 = 干得好」。实际上破限可能只是市场走到了情景边缘，触发的是流程而不是处分；而长期从不破限，往往说明情景集定得太松，或者业务量在悄悄收缩。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>限额的货币是情景损失：Gamma、Vega、Vanna、Charm 都折进统一的情景网格才可比。</li><li>聚合先聚仓位再算损失；跨标的要保留相关性趋一的压力限额。</li><li>限额分四层，软硬与审批人事先写死；到期与 Pin 用专项限额。</li><li>收盘净额之外要有日内峰值，路径风险不是快照能看到的。</li><li>口径变更等于限额变更，走同一审批；长期不破限是情景集太松的信号。</li><li>出处：据 Hull, <em>Options, Futures, and Other Derivatives</em>；情景限额与聚合治理据期权做市实务整理。</li></ul>',6))])}const c=A(p,[["render",d]]);export{T as __pageData,c as default};
